<?php
$products=$db->query("SELECT id_produk,sku,nama_produk,stok,satuan,harga_beli FROM tbl_produk WHERE status_produk='aktif' ORDER BY nama_produk")->fetchAll();
$suppliers=$db->query("SELECT id_supplier,nama_supplier FROM tbl_supplier WHERE status_supplier='aktif' ORDER BY nama_supplier")->fetchAll();
$recent=$db->query("SELECT pb.id_penerimaan,pb.no_penerimaan,pb.waktu_penerimaan,pb.status_penerimaan,u.nama_lengkap,COALESCE(s.nama_supplier,'Supplier tidak ditentukan') supplier,COUNT(dp.id_detail_penerimaan) item FROM tbl_penerimaan_barang pb JOIN tbl_pengguna u ON u.id_pengguna=pb.id_pengguna LEFT JOIN tbl_supplier s ON s.id_supplier=pb.id_supplier LEFT JOIN tbl_detail_penerimaan_barang dp ON dp.id_penerimaan=pb.id_penerimaan GROUP BY pb.id_penerimaan ORDER BY pb.id_penerimaan DESC LIMIT 10")->fetchAll();
$prefill=(int)($_GET['product']??0);
?>
<div class="page-heading"><div><span class="section-kicker">PERSEDIAAN BARANG</span><h1>Stok Masuk</h1><p>Catat penerimaan barang. Stok produk bertambah otomatis dan riwayat mutasi tersimpan.</p></div></div>
<div class="row g-3"><div class="col-xl-5"><div class="panel-card"><div class="panel-header"><div><h5>Catat Barang Masuk</h5><p>Tambahkan satu atau beberapa produk.</p></div><span class="panel-icon"><i class="bi bi-box-arrow-in-down"></i></span></div><form method="post" id="stockForm"><?=Csrf::field()?><input type="hidden" name="action" value="receive_stock"><input type="hidden" name="_return" value="stock"><div class="mb-3"><label class="form-label">Supplier</label><select class="form-select" name="id_supplier"><option value="">Supplier umum / tidak ditentukan</option><?php foreach($suppliers as $s):?><option value="<?=$s['id_supplier']?>"><?=e($s['nama_supplier'])?></option><?php endforeach;?></select><?php if(Auth::isAdmin()):?><a class="text-link small d-inline-block mt-2" href="<?=e(url('suppliers'))?>"><i class="bi bi-plus-circle me-1"></i>Kelola supplier</a><?php endif;?></div>
<div class="stock-lines" id="stockLines"><div class="stock-line-row"><div class="mb-2"><label class="form-label">Produk</label><select class="form-select" name="id_produk[]" required><option value="">Pilih produk</option><?php foreach($products as $p):?><option value="<?=$p['id_produk']?>" <?= $prefill===(int)$p['id_produk']?'selected':'' ?>><?=e($p['nama_produk'])?> · Stok <?=$p['stok']?></option><?php endforeach;?></select></div><div class="row g-2"><div class="col-6"><label class="form-label">Jumlah Masuk</label><input class="form-control" type="number" name="jumlah[]" min="1" value="1" required></div><div class="col-6"><label class="form-label">Harga Beli / Unit</label><input class="form-control" type="number" name="harga_beli[]" min="0" step="100" value="0"></div></div></div></div>
<button type="button" class="btn btn-outline-primary btn-sm mt-2" id="addStockLine"><i class="bi bi-plus-lg me-1"></i>Tambah Baris Produk</button><div class="mt-3"><label class="form-label">Catatan</label><textarea class="form-control" rows="2" name="catatan" placeholder="Nomor faktur atau catatan penerimaan"></textarea></div><div class="form-hint mt-3"><i class="bi bi-info-circle me-1"></i>Setelah disimpan, stok langsung bertambah. Pastikan jumlah barang sudah sesuai.</div><button class="btn btn-primary w-100 mt-3"><i class="bi bi-check2-circle me-2"></i>Simpan Penerimaan Barang</button></form></div></div>
<div class="col-xl-7"><div class="panel-card h-100"><div class="panel-header"><div><h5>Riwayat Penerimaan</h5><p>10 pencatatan stok masuk terakhir.</p></div><span class="panel-icon"><i class="bi bi-clock-history"></i></span></div><div class="table-responsive"><table class="table app-table align-middle"><thead><tr><th>No. Penerimaan</th><th>Supplier</th><th>Petugas</th><th>Waktu</th><th>Item</th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="5" class="empty-state">Belum ada penerimaan barang.</td></tr><?php endif;?><?php foreach($recent as $r):?><tr><td><b class="small"><?=e($r['no_penerimaan'])?></b><small class="d-block"><?=status_badge($r['status_penerimaan'])?></small></td><td><?=e($r['supplier'])?></td><td><?=e($r['nama_lengkap'])?></td><td><?=e(date('d/m/Y H:i',strtotime($r['waktu_penerimaan'])))?></td><td><?=(int)$r['item']?> produk</td></tr><?php endforeach;?></tbody></table></div></div></div></div>
